'use client'

// Reading view for a summary generated by the TRACE engine from the student's own file (POST /api/v1/practice/summary).
// Every bullet carries its page citation (file + page). Only texts that passed the guards (shown_allowed) are shown.
import { useMemo, useState } from 'react'
import { AlertTriangle, ArrowLeft, BookOpenText, FileText, ListChecks, Printer, RotateCcw, Sigma } from 'lucide-react'
import type { Lang } from '@/lib/translations'
import { MathText } from './math-text'
import { cn } from '@/lib/utils'

type SafeText = { text: string; shown_allowed: boolean }
type Source = { file: string; page?: number | null }
type Point = { text: SafeText; sources: Source[] }
export type PracticeSummary = {
  summary_id: string
  title?: SafeText | null
  overview?: SafeText | null
  sections: { heading: SafeText; points: Point[] }[]
  formulas: Point[]
  mistakes: Point[]
  sources: Source[]
  note: string
  refused?: string | null
}

const COPY: Record<Lang, Record<string, string>> = {
  en: { back: 'Home', again: 'New summary', print: 'Print', contents: 'Contents', formulas: 'Key formulas', mistakes: 'Common mistakes', sources: 'Sources', page: 'p.', overview: 'Overview', points: 'points', generated: 'Generated summary' },
  fr: { back: 'Accueil', again: 'Nouveau résumé', print: 'Imprimer', contents: 'Sommaire', formulas: 'Formules clés', mistakes: 'Erreurs fréquentes', sources: 'Sources', page: 'p.', overview: 'Aperçu', points: 'points', generated: 'Résumé généré' },
  ar: { back: 'الرئيسية', again: 'ملخص جديد', print: 'طباعة', contents: 'المحتويات', formulas: 'الصيغ الأساسية', mistakes: 'أخطاء شائعة', sources: 'المصادر', page: 'ص', overview: 'نظرة عامة', points: 'نقاط', generated: 'ملخص مولّد' },
}
const shown = (s?: SafeText | null) => (s && s.shown_allowed ? s.text : '')

function Cite({ sources, label }: { sources: Source[]; label: string }) {
  return (
    <>
      {sources.map((s, k) => (
        <span key={k} title={s.file} className="ms-1.5 inline-flex items-center rounded-full bg-secondary px-2 py-0.5 align-middle text-[11px] font-semibold text-primary-deep" dir="ltr">
          {label} {s.page}
        </span>
      ))}
    </>
  )
}

export function SummaryReader({ summary, lang, contentLang, onBack, onNew }: { summary: PracticeSummary; lang: Lang; contentLang: Lang; onBack: () => void; onNew: () => void }) {
  const c = COPY[lang]
  const formulas = summary.formulas.filter((p) => shown(p.text))
  const mistakes = summary.mistakes.filter((p) => shown(p.text))
  // the model sometimes also writes a "Key formulas" / "Common mistakes" section: hide it when the dedicated block exists
  const dup = (h: string) => {
    const x = h.trim().toLowerCase()
    return (formulas.length > 0 && Object.values(COPY).some((k) => k.formulas.toLowerCase() === x)) ||
      (mistakes.length > 0 && Object.values(COPY).some((k) => k.mistakes.toLowerCase() === x))
  }
  const sections = useMemo(() => summary.sections.filter((s) => shown(s.heading) && !dup(shown(s.heading)) && s.points.some((p) => shown(p.text))), [summary]) // eslint-disable-line react-hooks/exhaustive-deps
  const [active, setActive] = useState(0)
  const files = Array.from(new Set(summary.sources.map((s) => s.file)))
  const go = (id: string, i: number) => { setActive(i); document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }

  return (
    <div className="mx-auto grid w-full max-w-6xl gap-6 px-4 py-8 md:px-8 lg:grid-cols-[15rem_minmax(0,1fr)] lg:py-10">
      <aside className="flex flex-col gap-4 lg:sticky lg:top-20 lg:self-start print:hidden">
        <nav aria-label={c.contents} className="rounded-3xl border border-border bg-card p-4 shadow-sm">
          <p className="mb-2 px-2 text-xs font-bold uppercase tracking-[0.14em] text-muted-foreground">{c.contents}</p>
          <ol className="flex flex-col gap-1" dir={contentLang === 'ar' ? 'rtl' : 'ltr'}>
            {sections.map((s, i) => (
              <li key={i}>
                <button type="button" onClick={() => go(`sum-sec-${i}`, i)} className={cn('flex w-full items-start gap-2 rounded-xl px-2 py-2 text-start text-sm transition hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring', active === i ? 'bg-secondary font-semibold text-primary-deep' : 'text-foreground')}>
                  <span className="mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[11px] font-bold text-primary">{i + 1}</span>
                  <span className="min-w-0">{shown(s.heading)}</span>
                </button>
              </li>
            ))}
            {formulas.length ? <li><button type="button" onClick={() => go('sum-formulas', -1)} className="flex w-full items-center gap-2 rounded-xl px-2 py-2 text-start text-sm text-foreground hover:bg-muted"><Sigma className="size-4 text-primary" aria-hidden="true" />{c.formulas}</button></li> : null}
            {mistakes.length ? <li><button type="button" onClick={() => go('sum-mistakes', -2)} className="flex w-full items-center gap-2 rounded-xl px-2 py-2 text-start text-sm text-foreground hover:bg-muted"><AlertTriangle className="size-4 text-primary" aria-hidden="true" />{c.mistakes}</button></li> : null}
          </ol>
        </nav>
        <div className="flex flex-col gap-2">
          <button type="button" onClick={onNew} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 font-semibold transition hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><RotateCcw className="size-4" aria-hidden="true" />{c.again}</button>
          <button type="button" onClick={() => window.print()} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 font-semibold transition hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><Printer className="size-4" aria-hidden="true" />{c.print}</button>
          <button type="button" onClick={onBack} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-primary px-4 font-bold text-primary-foreground transition hover:bg-primary-deep focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><ArrowLeft className="size-4 rtl:rotate-180" aria-hidden="true" />{c.back}</button>
        </div>
      </aside>

      <article className="flex flex-col gap-6" dir={contentLang === 'ar' ? 'rtl' : 'ltr'} lang={contentLang}>
        <header className="rounded-[2rem] border border-border bg-gradient-to-br from-accent via-card to-secondary/70 p-6 shadow-sm sm:p-8">
          <span className="inline-flex items-center gap-2 rounded-full border border-primary/20 bg-secondary px-3 py-1.5 text-xs font-bold uppercase tracking-[0.14em] text-primary-deep"><BookOpenText className="size-4" aria-hidden="true" />{c.generated}</span>
          <h1 className="mt-4 text-balance text-3xl font-bold leading-tight tracking-tight sm:text-4xl">{shown(summary.title) || files[0]}</h1>
          {shown(summary.overview) ? <p className="mt-3 max-w-3xl text-pretty text-base leading-relaxed text-muted-foreground sm:text-lg">{shown(summary.overview)}</p> : null}
        </header>

        {sections.map((s, i) => (
          <section key={i} id={`sum-sec-${i}`} className="scroll-mt-24 rounded-3xl border border-border bg-card p-6 shadow-sm sm:p-8">
            <div className="mb-4 flex items-center gap-3">
              <span className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-secondary text-sm font-bold text-primary">{i + 1}</span>
              <h2 className="text-xl font-bold leading-snug">{shown(s.heading)}</h2>
            </div>
            <ul className="flex flex-col gap-3">
              {s.points.filter((p) => shown(p.text)).map((p, k) => (
                <li key={k} className="flex gap-3 text-pretty text-base leading-relaxed text-foreground">
                  <span className="mt-2.5 size-1.5 shrink-0 rounded-full bg-primary" aria-hidden="true" />
                  <span><MathText text={shown(p.text)} /><Cite sources={p.sources} label={c.page} /></span>
                </li>
              ))}
            </ul>
          </section>
        ))}

        {formulas.length ? (
          <section id="sum-formulas" className="scroll-mt-24 rounded-3xl border border-border bg-card p-6 shadow-sm sm:p-8">
            <h2 className="mb-4 flex items-center gap-2 text-xl font-bold"><Sigma className="size-5 text-primary" aria-hidden="true" />{c.formulas}</h2>
            <ul className="grid gap-3 sm:grid-cols-2">
              {formulas.map((p, k) => (
                <li key={k} className="rounded-2xl border border-border bg-muted/40 p-4">
                  <span className="block text-base font-semibold text-foreground"><MathText text={shown(p.text)} formula /></span>
                  <Cite sources={p.sources} label={c.page} />
                </li>
              ))}
            </ul>
          </section>
        ) : null}

        {mistakes.length ? (
          <section id="sum-mistakes" className="scroll-mt-24 rounded-3xl border border-border bg-card p-6 shadow-sm sm:p-8">
            <h2 className="mb-4 flex items-center gap-2 text-xl font-bold"><AlertTriangle className="size-5 text-primary" aria-hidden="true" />{c.mistakes}</h2>
            <ul className="flex flex-col gap-3">
              {mistakes.map((p, k) => (
                <li key={k} className="flex gap-3 rounded-2xl bg-destructive/10 px-4 py-3 text-base leading-relaxed text-foreground">
                  <ListChecks className="mt-1 size-4 shrink-0 text-destructive" aria-hidden="true" />
                  <span><MathText text={shown(p.text)} /><Cite sources={p.sources} label={c.page} /></span>
                </li>
              ))}
            </ul>
          </section>
        ) : null}

        <footer className="rounded-3xl border border-border bg-background/70 p-5 text-sm text-muted-foreground" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
          <p className="mb-2 flex items-center gap-2 font-semibold text-foreground"><FileText className="size-4 text-primary" aria-hidden="true" />{c.sources}</p>
          <ul className="flex flex-wrap gap-2">
            {files.map((f) => (
              <li key={f} className="rounded-full border border-border bg-card px-3 py-1 text-xs" dir="ltr">
                {f} · {c.page} {summary.sources.filter((s) => s.file === f).map((s) => s.page).join(', ')}
              </li>
            ))}
          </ul>
          <p className="mt-3 text-xs">{summary.note}</p>
        </footer>
      </article>
    </div>
  )
}
